cd /workspace/SuperGrok1.5; set +o pipefail 2>/dev/null
echo "=== scan ALL third-party imports across tree, check which are NOT installed ==="
python3 - <<'PY'
import ast, glob, importlib.util, sys
stdlib=set(sys.stdlib_module_names)
local={'grokking_optimizers','tests','tuning','scripts','csrc','examples','grokking_race_v2','wiring_check','bench_backends'}
thirdparty=set()
for f in glob.glob("**/*.py", recursive=True):
    if any(s in f for s in ("third_party/","_dectc_codegen/","claude_session_archive/","__pycache__/")): continue
    try: tree=ast.parse(open(f,encoding="utf-8",errors="ignore").read())
    except: continue
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names: thirdparty.add(a.name.split(".")[0])
        elif isinstance(n, ast.ImportFrom) and n.level==0 and n.module:
            thirdparty.add(n.module.split(".")[0])
ext=sorted(m for m in thirdparty if m not in stdlib and m not in local and not m.startswith("_"))
missing=[m for m in ext if importlib.util.find_spec(m) is None]
print("third-party imported:", ext)
print("MISSING (not installed):", missing)
PY

