export const meta = {
  name: 'supergrok-implement',
  description: 'Parallel READ-ONLY implementation: 5 agents each produce an exact-edit spec (verbatim old->new + new files) for the lead to apply+build+gate on the main tree',
  phases: [{ title: 'Implement', detail: '5 agents read code+drafts and emit precise apply-ready edit specs to /workspace/impl_diffs/' }],
}
const SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['area','spec_path','files_changed','gate_commands','confidence','risks'],
  properties: {
    area: { type: 'string' },
    spec_path: { type: 'string', description: '/workspace/impl_diffs/<area>.md — the exact-edit spec the lead applies.' },
    files_changed: { type: 'array', items: { type: 'string' } },
    gate_commands: { type: 'array', items: { type: 'string' }, description: 'Exact command(s) the lead should run to build + gate after applying.' },
    confidence: { type: 'string', description: 'high/med/low that this applies+builds+gates cleanly, + why.' },
    risks: { type: 'array', items: { type: 'string' } },
  },
}
const COMMON = `You are READ-ONLY on the repo at /workspace/SuperGrok1.5 (Read/Grep/Glob freely; do NOT edit the repo, do NOT build/run). Deliverable: write /workspace/impl_diffs/<AREA>.md containing your COMPLETE implementation as APPLY-READY edits — for EACH file to change, give the EXACT current snippet to replace (copy it VERBATIM from the live file, enough lines to be unique) and the replacement, as clearly-delimited OLD/NEW blocks; give any NEW files in full. The lead applies them with exact-match edits, then builds+gates. Be precise: a mismatched OLD block fails to apply. PROJECT RULES: production path = L3-TC persistent wgmma megakernel; HARD gate = fp64 parity (rel 1e-4; SAM 2.5e-2) + A/A/A bit-determinism; legal rewrites transport-only (preserve ascending-k fp32 order); NEW knobs byte-identical when OFF (#if-erase to pre-knob kernel); gfx942/tpu_v6e preserved; compile-file additions stay GENERIC/portable (no SuperGrok-hardcoding). Read the cited drafts in full first.`

const agents = [
  { name:'compile', label:'compile.py additions+bugfixes', prompt:`${COMMON}
AREA: grokking_optimizers/compile.py. Read drafts /workspace/phase2/{s34_and_bugs,s14_l2persist,s15_smem_carveout}.md AND the cited compile.py regions. Produce apply-ready edits for: (A) the 3 verified bug-fixes — dead device_profiling import (~17652; either inline run_device_pgo_round or add the alias), resolve_extra_hipcc_flags -1 maxrregcount sentinel (~3424; mirror the NVCC skip ~3355), inert ABI guard (add the Python __abi_schema__ assert vs bindings.cpp GROK_ABI_SCHEMA); (B) S3.4 cross-run negative cache + bloom dedup; (C) S1.4 L2-persistence tuned dim (kernel L2PersistScope exists — add the compile.py _dim + macro + plumbing); (D) S1.5 smem-carveout tuned knobs. All new dims byte-identical at default. gate_commands: ['python -m grokking_optimizers.compile --self-test', 'ruff check grokking_optimizers/']. Spec -> /workspace/impl_diffs/compile.md.` },

  { name:'cute', label:'CuTe GEMM rewrite (wgmma.cuh)', prompt:`${COMMON}
AREA: csrc/backends/cuda/sm_90/wgmma.cuh ONLY. Read /workspace/cute_plan/{IMPLEMENTATION_PLAN,CUTE_GEMM_SYNTHESIS,WGMMA_ENGINE_SEAM}.md + the live wgmma.cuh IN FULL + the cited CuTe headers under third_party/cutlass/include/cute/. Produce apply-ready edits implementing CuTe-atom steps 1-3 (descriptor->cute::GmmaDescriptor; issue->cute::SM90::GMMA::MMA_64xNx16_F32BF16BF16_SS<Major::K,Major::K>::fma; fence/commit/wait->cute warpgroup_*), ALL behind a new SG_TUNED_GEMM_ENGINE macro (default 0 = existing hand PTX byte-identical; 1 = CuTe). DEFER TMA+swizzle. KEEP the sg::sm90::wgs:: ABI exactly (WgmmaAccum<N> with .c[i], make_desc_{A,B}_kmajor, wgmma_m64nNk16_bf16<N,ScaleD,0,0>, fence/commit/wait, wgmma_frag_decode) so NO call site changes. Give the exact #include lines to add + the exact per-N atom dispatch. gate_commands: ['CUDA_VISIBLE_DEVICES=0 bash scripts/compile_to_object.sh csrc/backends/cuda/sm_90/wgmma_selftest.cu -DSG_TUNED_GEMM_ENGINE=1', 'CUDA_VISIBLE_DEVICES=0 GATE_SEED=42 python -m pytest tests/hw/test_decoder_tc.py -q']. Spec -> /workspace/impl_diffs/cute.md. Be honest in confidence (CuTe is finicky).` },

  { name:'flagship', label:'flagship codegen (d,layers,vocab,seq)', prompt:`${COMMON}
AREA: grokking_optimizers/megakernel_codegen.py + csrc/fused/sm_90/decoder_layout.cuh. Read _decoder_layout_body(d)/decoder_layout_header() (~602/694) + decoder_layout.cuh IN FULL + MODEL_SCALES_BY_MODEL['flagship'] (grokking_race_v2.py:251). Today it is parameterized by WIDTH d only and hardcodes layers=2/vocab=99/seq=4. Produce apply-ready edits to parameterize the emitter by (d, layers, vocab, seq) and add a path to emit a FLAGSHIP decoder layout (d=1600, layers=48) — the __constant__ kDecOffsets/kDecSizes for L layers, the dec_layout_check static_asserts, kDecTotalElems. Keep the existing d=128/d=2048 layouts byte-identical. gate_commands: ['python -m grokking_optimizers.megakernel_codegen --decoder-layout <flagship-flags> > /tmp/dl.cuh && bash scripts/compile_to_object.sh csrc/fused/sm_90/mega_decoder_real_adamw_tc.cu -DWITH_CUTLASS -DSG_TUNED_GEMM_IMPL=1 (with the flagship layout) ; check ptxas -v regs/smem + occupancy>=1']. Note in risks whether 1.5B/L48 likely fits 1-CTA/SM (smem). Spec -> /workspace/impl_diffs/flagship.md.` },

  { name:'datasets', label:'datasets Layer A + dead-code', prompt:`${COMMON}
AREA: grokking_race_v2.py. Read /workspace/phase3/{harness_changes,decoder_fineweb,vit_imagenet,mamba_gifteval}.md + /workspace/phase5/deadcode.md + the cited race regions (make_data_for_task@372, evaluate@536, EarlyStopper@542, _progressive_eval_freq@696, DEFAULT_CONFIG@259). Produce apply-ready edits for: Layer-A data plumbing ONLY — make_data_for_task dispatch on a new DEFAULT-OFF c['data_source'] returning (streaming train iterator, FIXED eval probe); a fixed-probe-capped evaluate path (seconds not minutes); the loss-PLATEAU EarlyStopper criterion for LM/forecasting (KEEP 0.95 accuracy for ViT). DEFAULT-OFF so the mod-97 path is BYTE-IDENTICAL (kernels are size-pinned; Layer-B resize NOT in scope — stub dataset sources behind an importable interface, no downloads). PLUS remove the provably-dead in-file MambaModel/SelectiveSSMLayer + _maybe_wrap_cuda_graph no-op (confirm reachability). gate_commands: ['python grokking_race_v2.py --gpus 2 --optimizers adamw --num-seeds 1 --early-stop-max-steps 300 --no-status-server --output /tmp/smoke', 'python -c \"import grokking_race_v2\"']. Spec -> /workspace/impl_diffs/datasets.md.` },

  { name:'verify', label:'Phase-4 verification harness', prompt:`${COMMON}
AREA: NEW files only (no edits to existing kernels). Read /workspace/phase4/verify_harness.md + tests/hw/test_l3tc_tail_gate.py (run_cell_gate) + verify_all.py. Produce the FULL content of a new harness (e.g. tests/hw/verify_functions.py) that runs the sm_90 L3-TC isolation + ablation/wiring matrix leveraging the existing gates, 8-GPU-shardable (process-per-GPU over the 33-cell list), with a CPU --self-check that enumerates the function/cell surface without a GPU run. Preserve gfx942/tpu. gate_commands: ['python tests/hw/verify_functions.py --self-check']. Spec -> /workspace/impl_diffs/verify.md (give the new file(s) in full).` },
]

phase('Implement')
const results = await parallel(agents.map(a => () =>
  agent(a.prompt, { label:a.label, phase:'Implement', schema:SCHEMA })
    .then(r => ({ name:a.name, ...(r || { area:a.name, spec_path:'', files_changed:[], gate_commands:[], confidence:'AGENT NULL', risks:['agent died'] }) }))))
log(`Impl specs complete: ${results.filter(r=>r&&r.spec_path).length}/${agents.length}`)
return results

# ── HILL-CLIMB BENCH VARIANT (d-scaled decoder) ──────────────────────────────
# The persistent megakernel's compute roofline is diagnosed/optimized at a LARGE
# model width. _DEC_BENCH_D is the width the d-scaled BENCHMARK build compiles at;
# it does NOT touch the production d=128 path. decoder_layout_header() emits BOTH
# layouts into ONE header, selected by the compile flag SG_DEC_BENCH_LAYOUT (set
# ONLY by the bench TU / the _ops_bench variant; UNSET → the production d=128
# constants, byte-identical default). So the committed header carries both, the
# production _ops always sees d=128, and the variant build flips ONE flag. The
# proven end-to-end d (task #13 context: parity 2.4e-07, A/A/A) is 1024.
_DEC_BENCH_D = 2048


def _decoder_param_sizes(d: int = _DEC_D) -> List[int]:
    """Per-tensor numel in named_parameters() order (mirror of decoder_oracle.py
    decoder_param_spec()). 30 tensors; at d=128 total 422755. `d` is parametric
    so the d-scaled bench layout (SG_DEC_BENCH_LAYOUT) reuses the SAME shape
    formula — the per-tensor shapes are all functions of (d, dff=4d, vocab, seq),
    so a single d controls the whole table."""
    dff, v, seq = 4 * d, _DEC_VOCAB, _DEC_SEQ
    sizes = [v * d, seq * d]                      # tok, pos
    for _ in range(_DEC_LAYERS):
        sizes += [
            3 * d * d, 3 * d,                     # attn.in_proj_weight/bias
            d * d, d,                             # attn.out_proj.weight/bias
            d, d, d, d,                           # n1.w/b, n2.w/b
            dff * d, dff,                         # ff.0.weight/bias
            d * dff, d,                           # ff.2.weight/bias
        ]
    sizes += [d, d, v * d, v]                     # norm.w/b, out.weight/bias
    return sizes


def _decoder_layout_body(d: int) -> str:
    """The constants + __constant__ tables + compile-time cross-check for ONE
    decoder width `d`. Emitted into ONE of the SG_DEC_BENCH_LAYOUT branches; the
    branches are mutually exclusive at preprocess time, so reusing the SAME symbol
    names (kDecOffsets/kDecSizes/dec_layout_check) across both is safe."""
    sizes = _decoder_param_sizes(d)
    offsets, acc = [], 0
    for n in sizes:
        offsets.append(acc)
        acc += n
    total = acc
    n_tensors = len(sizes)

    def _fmt(arr):
        # 10 per line for readability.
        rows = []
        for i in range(0, len(arr), 10):
            rows.append("    " + ", ".join(str(x) for x in arr[i:i + 10]))
        return ",\n".join(rows)

    sizes_block = _fmt(sizes)
    offsets_block = _fmt(offsets)
    return f"""constexpr int SG_DEC_VOCAB  = {_DEC_VOCAB};
constexpr int SG_DEC_D      = {d};
